def feature(s):
    s = s or {}
    v = s.get('volume_per_atom_A3')
    if v is None or v <= 0:
        return 0.0
    props = s.get('element_properties') or {}
    total = 0.0
    weight = 0.0
    for el, x in (s.get('composition') or {}).items():
        r = (props.get(el) or {}).get('covalent_radius_A')
        if r is not None and r > 0 and x > 0:
            total += x * r * r * r
            weight += x
    return float(4.0 * pi * total / (3.0 * v * weight)) if weight > 0 else 0.0

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    radii = [(props.get(a.get('element')) or {}).get('covalent_radius_A') for a in sites]
    nearest = [None for a in sites]
    for b in s.get('neighbors') or []:
        i, j = b['i'], b['j']
        ri, rj = radii[i], radii[j]
        d = b.get('distance_A')
        if ri is not None and rj is not None and ri > 0 and rj > 0 and d is not None and d > 0:
            q = d / (ri + rj)
            if nearest[i] is None or q < nearest[i]:
                nearest[i] = q
    total = 0.0
    weight = 0.0
    for a, q in zip(sites, nearest):
        w = a.get('occupancy', 1.0)
        if q is not None and w is not None and w > 0:
            total += w * q
            weight += w
    return float(total / weight) if weight > 0 else 0.0

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    radii = [(props.get(a.get('element')) or {}).get('covalent_radius_A') for a in sites]
