    for b in s.get('neighbors') or []:
        i, j = b['i'], b['j']
        ri, rj = radii[i], radii[j]
        d = b.get('distance_A')
        if ri is not None and rj is not None and ri > 0 and rj > 0 and d is not None and d > 0:
            q = d / (ri + rj)
            if nearest[i] is None or q < nearest[i]:
                nearest[i] = q
    wsum = 0.0
    first = 0.0
    second = 0.0
    for a, q in zip(sites, nearest):
        w = a.get('occupancy', 1.0)
        if q is not None and w is not None and w > 0:
            wsum += w
            first += w * q
            second += w * q * q
    return float(sqrt(max(0.0, second / wsum - (first / wsum) ** 2))) if wsum > 0 else 0.0

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    radii = [(props.get(a.get('element')) or {}).get('covalent_radius_A') for a in sites]
    occ = [max(0.0, a.get('occupancy', 1.0) or 0.0) for a in sites]
    total = 0.0
    for b in s.get('neighbors') or []:
        i, j = b['i'], b['j']
        ri, rj = radii[i], radii[j]
        d = b.get('distance_A')
        if ri is not None and rj is not None and ri > 0 and rj > 0 and d is not None and d > 0:
            q = d / (1.2 * (ri + rj))
            if q < 2.0:
                total += occ[i] * occ[j] * exp(-(q ** 6))
    den = sum(occ)
    return float(total / den) if den > 0 else 0.0

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    radii = [(props.get(a.get('element')) or {}).get('covalent_radius_A') for a in sites]
    occ = [max(0.0, a.get('occupancy', 1.0) or 0.0) for a in sites]
    coord = [0.0 for a in sites]
    for b in s.get('neighbors') or []:
        i, j = b['i'], b['j']
        ri, rj = radii[i], radii[j]
        d = b.get('distance_A')
        if ri is not None and rj is not None and ri > 0 and rj > 0 and d is not None and d > 0:
            q = d / (1.2 * (ri + rj))
            if q < 2.0:
                coord[i] += occ[j] * exp(-(q ** 6))
    den = sum(occ)
    if den <= 0:
        return 0.0
    mean = sum(w * c for w, c in zip(occ, coord)) / den
    var = sum(w * (c - mean) ** 2 for w, c in zip(occ, coord)) / den
    return float(sqrt(max(0.0, var)) / (mean + 0.1))

