    sites = s.get('sites') or []
    occ = [max(0.0, a.get('occupancy', 1.0) or 0.0) for a in sites]
    nearest = [None for a in sites]
    for b in s.get('neighbors') or []:
        i = b['i']
        d = b.get('distance_A')
        if d is not None and d > 0 and (nearest[i] is None or d < nearest[i]):
            nearest[i] = d
    total = 0.0
    for b in s.get('neighbors') or []:
        i, j = b['i'], b['j']
        d = b.get('distance_A')
        if nearest[i] is not None and d is not None and 0 < d <= 1.3 * nearest[i]:
            total += occ[i] * occ[j]
    den = sum(occ)
    return float(total / den) if den > 0 else 0.0

