def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    en = [(props.get(a.get('element')) or {}).get('eneg') for a in sites]
    occ = [max(0.0, a.get('occupancy', 1.0) or 0.0) for a in sites]
    den = sum(occ[i] for i in range(len(sites)) if en[i] is not None)
    if den <= 0:
        return 0.0
    mean = sum(occ[i] * en[i] for i in range(len(sites)) if en[i] is not None) / den
    charges = [mean - value if value is not None else 0.0 for value in en]
    total = 0.0
    for b in s.get('neighbors') or []:
        i, j = b['i'], b['j']
        d = b.get('distance_A')
        if d is not None and 0 < d < 6.0 and en[i] is not None and en[j] is not None:
            kernel = 1.0 / d - 1.0 / 6.0 + (d - 6.0) / 36.0
            total += occ[i] * occ[j] * charges[i] * charges[j] * kernel
    return float(0.5 * total / den)
